    {
      id: "wp2wd-evidence19",
      revision: "r1",
      mode: "evidence-detective",
      prompt: "A hilltop area in Alberta has poor pressure that began the week a new pressure zone boundary was commissioned nearby.",
      topicId: "pressure-zones",
      level: "class1",
      assumptions: "Fictional hilltop area in a Red Deer area system. Zone boundaries were redrawn and two boundary valves were operated during commissioning.",
      evidence: [
        {
          id: "ev1",
          label: "Hilltop pressure fell from 340 kPa to 190 kPa in the commissioning week and stayed there."
        },
        {
          id: "ev2",
          label: "Streets just below the hilltop, moved to the new low zone, have normal pressure for that zone."
        },
        {
          id: "ev3",
          label: "One boundary valve between the hilltop and the high zone is found closed, though the commissioning plan shows it open."
        },
        {
          id: "ev4",
          label: "Opening that valve in a trial restores hilltop pressure to 335 kPa."
        },
        {
          id: "ev5",
          label: "No demand growth or breaks occurred on the hilltop that week."
        }
      ],
      inference: {
        id: "inference",
        prompt: "Which explanation is best supported by all of the observations?",
        options: [
          {
            id: "inf-a",
            label: "The new low zone is stealing the hilltop supply through the boundary"
          },
          {
            id: "inf-b",
            label: "Hilltop homes need individual booster pumps from now on"
          },
          {
            id: "inf-c",
            label: "The hilltop was cut off from its high zone feed by a boundary valve left closed at commissioning"
          },
          {
            id: "inf-d",
            label: "The hilltop main suddenly tuberculated during commissioning week"
          }
        ],
        correctOptionId: "inf-c",
        explanation: "Timing matches commissioning, the plan shows the valve open while it is found closed, and a trial opening restores pressure fully. Tuberculation does not occur in a week, and individual boosters are not needed once the intended feed is restored."
      },
      nextClue: {
        id: "next-clue",
        prompt: "Which next check best confirms the explanation and guides the fix?",
        options: [
          {
            id: "nc-a",
            label: "Open and verify the boundary valve, then audit every boundary valve position against the commissioning plan"
          },
          {
            id: "nc-b",
            label: "Install booster pumps at hilltop homes at utility cost"
          },
          {
            id: "nc-c",
            label: "Move the hilltop into the low zone permanently"
          }
        ],
        correctOptionId: "nc-a",
        explanation: "A full boundary audit prevents other commissioning errors from hiding elsewhere in the redrawn zones."
      },
      clueText: {
        "nc-a": "The audit finds all other valves as planned, and hilltop pressure holds normal for a month.",
        "nc-b": "Boosters treat a valve position error as a design problem and add cost without need.",
        "nc-c": "The low zone cannot serve the hilltop elevation at adequate pressure, as its own setpoint shows."
      }
    }
